@app.route('/api/upload', methods=['POST'])
def upload_file():
    try:
        if 'file' not in request.files:
            return jsonify({"error": "Nincs fájl csatolva"}), 400

        file = request.files['file']

        if file.filename == '':
            return jsonify({"error": "Nincs kiválasztott fájl"}), 400

        if not allowed_file(file.filename):
            return jsonify({"error": f"Nem támogatott fájltípus. Engedélyezett: {', '.join(ALLOWED_EXTENSIONS)}"}), 400

        filename = secure_filename(file.filename)
        parts = filename.rsplit('.', 1)
        file_ext = parts[1].lower() if len(parts) > 1 else ''
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        unique_filename = f"{timestamp}_{filename}"
        filepath = os.path.join(app.config['UPLOAD_FOLDER'], unique_filename)

        file.save(filepath)

        file_size = os.path.getsize(filepath)

        content = ""
        if file_ext in {'txt', 'md', 'py', 'js', 'html', 'css', 'json', 'xml', 'csv'}:
            try:
                with open(filepath, 'r', encoding='utf-8') as f:
                    content = f.read(50000)
            except UnicodeDecodeError:
                content = "[Fájl tartalma nem olvasható UTF-8 kódolással]"
            except Exception as read_error:
                logger.error(f"Error reading file: {read_error}")
                content = "[Fájl tartalma nem olvasható szöveges formátumban]"
        elif file_ext in {'jpg', 'jpeg', 'png', 'gif'}:
            content = "[Képfájl feltöltve - elemzéshez használjon képfelismerő modellt]"
        elif file_ext in {'pdf', 'doc', 'docx'}:
            content = "[Dokumentum feltöltve - teljes elemzéshez használjon dokumentum feldolgozó eszközt]"
        else:
            content = "[Bináris fájl feltöltve]"

        analysis_prompt = f"""A felhasználó feltöltött egy fájlt:
Fájlnév: {filename}
Fájltípus: {file_ext}
Méret: {file_size} bájt

