@app.route('/api/exa/search_multi', methods=['POST'])
def exa_search_multi():
    try:
        data = request.json
        queries = data.get('queries', [])
        if not queries:
            return jsonify({"error": "Queries are required"}), 400

        results = []
        for query_data in queries:
            if not isinstance(query_data, dict):
                continue
            search_params = {
                'query': query_data.get('query'),
                'num_results': query_data.get('num_results', 100),
                'type': query_data.get('search_type', 'auto')
            }

            if query_data.get('category'):
                search_params['category'] = query_data['category']

            if not search_params['query']:
                continue

            search_result = exa_client.search(**search_params)
            results.append({
                'query': query_data.get('query'),
                'results': [
                    {
                        'title': r.title,
                        'url': r.url,
                        'author': r.author,
                        'published_date': r.published_date,
                        'score': getattr(r, 'score', None)
                    }
                    for r in search_result.results
                ]
            })

        return jsonify({'results': results})
    except Exception as e:
        logger.error(f"Search multi error: {str(e)}")
        return jsonify({"error": str(e)}), 500

